struct BfmeFreeListNode
{
	BfmeFreeListNode *m_next;
};

class BfmeAllocationResult
{
public:
	BfmeAllocationResult() {}
	void *value;
};

extern BfmeFreeListNode *bfmeFreeList[16];
void *bfmeSmallRefillPR(unsigned int bytes);

void *bfmeSmallAllocPR(unsigned int bytes)
{
	BfmeFreeListNode *volatile *myFreeList = bfmeFreeList + ((bytes - 1) >> 3);
	BfmeAllocationResult result;
	_STL::_Node_Alloc_Lock<false, 0> lockInstance;

	if ((result.value = *myFreeList) != 0)
		*myFreeList = static_cast<BfmeFreeListNode *>(result.value)->m_next;
	else
		result.value = bfmeSmallRefillPR(bytes);

	return result.value;
}
